<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Role; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Facades\DB; use Illuminate\Validation\Rule;
class UserController extends Controller {
 public function index(){return view('admin.users.index',['users'=>User::with('roles')->latest()->paginate(20)]);}
 public function create(){return view('admin.users.form',['user'=>new User,'roles'=>Role::orderBy('name')->get()]);}
 public function store(Request $r){$d=$r->validate(['name'=>['required','string','max:150'],'email'=>['required','email','max:190','unique:users,email'],'phone'=>['nullable','string','max:30'],'password'=>['required','string','min:12'],'is_active'=>['sometimes','boolean'],'roles'=>['nullable','array'],'roles.*'=>['integer','exists:roles,id']]);$user=DB::transaction(function()use($d,$r){$created=User::create(['name'=>$d['name'],'email'=>$d['email'],'phone'=>$d['phone']??null,'password'=>Hash::make($d['password']),'is_active'=>$r->boolean('is_active')]);$created->roles()->sync($d['roles']??[]);return $created;});return redirect()->route('admin.users.index')->with('success','User created.');}
 public function edit(User $user){return view('admin.users.form',['user'=>$user->load('roles'),'roles'=>Role::orderBy('name')->get()]);}
 public function update(Request $r,User $user){$d=$r->validate(['name'=>['required','string','max:150'],'email'=>['required','email','max:190',Rule::unique('users')->ignore($user->id)],'phone'=>['nullable','string','max:30'],'password'=>['nullable','string','min:12'],'is_active'=>['sometimes','boolean'],'roles'=>['nullable','array'],'roles.*'=>['integer','exists:roles,id']]);if($user->is($r->user())){if(!$r->boolean('is_active'))abort(422,'You cannot disable your own account.');$adminRoleId=Role::where('slug','administrator')->value('id');if(!in_array($adminRoleId,$d['roles']??[]))abort(422,'You cannot remove your own Administrator role.');}$user->fill(['name'=>$d['name'],'email'=>$d['email'],'phone'=>$d['phone']??null,'is_active'=>$r->boolean('is_active')]);if(!empty($d['password']))$user->password=Hash::make($d['password']);$user->save();$user->roles()->sync($d['roles']??[]);return back()->with('success','User updated.');}
 public function destroy(User $user){abort_if($user->is(request()->user()),422,'You cannot delete your own account.');if($user->isAdministrator()&&User::whereHas('roles',fn($q)=>$q->where('slug','administrator'))->count()<=1)abort(422,'The last Administrator account cannot be deleted.');$user->delete();return back()->with('success','User deleted.');}
}